1	/*!
2	 * \file tl/op/op.h
3	 * \brief Tile library operations.
4	 *
5	 */
6	
7	#ifndef TVM_TL_OP_OP_H_
8	#define TVM_TL_OP_OP_H_
9	
10	#include <array>
11	#include <cstdint>
12	#include <functional>
13	#include <optional>
14	#include <string>
15	#include <utility>
16	#include <vector>
17	
18	#include <tvm/arith/analyzer.h>
19	#include <tvm/ir/op.h>
20	#include <tvm/target/target.h>
21	#include <tvm/tirx/buffer.h>
22	#include <tvm/tirx/op.h>
23	#include <tvm/tirx/op_attr_types.h>
24	#include <tvm/tirx/stmt.h>
25	
26	#include "../layout/layout.h"
27	#include "support/check.h"
28	
29	namespace tvm {
30	namespace tl {
31	
32	using AddWorkspaceCallback = std::function<PrimExpr(int, DataType)>;
33	// Allocate a compiler-generated shared mbarrier slot. The optional hint names
34	// the backing barrier buffer when the first slot is created; later slots share
35	// the same buffer and may ignore the hint.
36	using AllocMBarrierCallback =
37	    std::function<int(int arrive_count, std::optional<std::string> name)>;
38	using UpdateBarrierArriveCallback = std::function<void(tirx::Var, PrimExpr)>;
39	// Record a minimum shared-memory base alignment (bytes) required for the
40	// buffer backed by the given data Var (e.g. TMA/MMA swizzle constraints).
41	using RequireSmemAlignmentCallback = std::function<void(tirx::Var, int)>;
42	using LayoutMap = ffi::Map<tirx::Buffer, Layout>;
43	using BufferMap = ffi::Map<tirx::Var, tirx::Buffer>;
44	using BlockAnnotations = ffi::Map<ffi::String, ffi::Any>;
45	
46	enum AccessMask : int {
47	  kAccessRead = 1,
48	  kAccessWrite = 2,
49	  kAccessReadWrite = kAccessRead | kAccessWrite,
50	};
51	
52	// Preserve known read/write bits and conservatively assume both when a mask
53	// cannot be resolved at compile time.
54	inline int GetConservativeAccessMask(const PrimExpr &rw_mask) {
55	  if (const auto *mask = rw_mask.as<IntImmNode>()) {
56	    return static_cast<int>(mask->value) & kAccessReadWrite;
57	  }
58	  return kAccessReadWrite;
59	}
60	
61	struct AccessRegion {
62	  tirx::BufferRegion region;
63	  int access_mask{kAccessReadWrite};
64	};
65	
66	struct AccessRegions {
67	  ffi::Array<tirx::BufferRegion> reads;
68	  ffi::Array<tirx::BufferRegion> writes;
69	};
70	
71	inline void AppendAccessRegionByMask(const AccessRegion &access,
72	                                     ffi::Array<tirx::BufferRegion> *reads,
73	                                     ffi::Array<tirx::BufferRegion> *writes) {
74	  if (!access.region.defined()) {
75	    return;
76	  }
77	  if (access.access_mask & kAccessRead) {
78	    reads->push_back(access.region);
79	  }
80	  if (access.access_mask & kAccessWrite) {
81	    writes->push_back(access.region);
82	  }
83	}
84	
85	enum class InferLevel : uint8_t {
86	  kFree = 0,
87	  kCommon = 1,
88	  kStrict = 2,
89	};
90	
91	/// Convert InferLevel enum to string for debugging
92	inline const char *InferLevelToString(InferLevel level) {
93	  switch (level) {
94	  case InferLevel::kFree:
95	    return "Free";
96	  case InferLevel::kCommon:
97	    return "Common";
98	  case InferLevel::kStrict:
99	    return "Strict";
100	  default:
101	    return "Unknown";
102	  }
103	}
104	
105	struct LowerArgs {
106	  Target target;
107	  Range thread_bounds;
108	  // Logical thread index consumed by lowering helpers. This is an expression
109	  // rather than a Var: GPU lowering passes the real threadIdx.x Var (bound by
110	  // a thread_extent AttrStmt), while targets without thread bindings (e.g.
111	  // CPU) pass constant 0. It must never be an unbound synthetic Var.
112	  PrimExpr thread_index;
113	  LayoutMap layout_map;
114	  ffi::Map<tirx::Buffer, tirx::Buffer> buffer_remap;
115	  // Map from Bind variable to its bound expression, for resolving
116	  // fragment buffer accesses through Bind values
117	  ffi::Map<tirx::Var, PrimExpr> bind_var_to_expr;
118	  // Fallback mbarrier parity for ops that do not carry an explicit
119	  // tl.pipeline_mbar_phase_expr annotation. LowerTileOp derives this from the
120	  // nearest enclosing serial loop so non-pipelined TMA loops still alternate
121	  // barrier phase correctly.
122	  PrimExpr mbar_phase_expr = IntImm(DataType::Int(32), 0);
123	  // Pointer to the shared.barrier buffer for compiler-generated mbarriers.
124	  // Points to the LowerTileOpPass member so copy.cc sees the buffer
125	  // even when created lazily by the alloc_mbarrier callback.
126	  ffi::Optional<tirx::Buffer> *mbarrier_buffer = nullptr;
127	  // Product of cluster_dims (from block annotation). Defaults to 1 (no
128	  // cluster). Used by TMA copy lowering to scale expect_tx bytes for cluster
129	  // barriers.
130	  int cluster_size = 1;
131	
132	  // Callbacks used by op lowerings to request pass-owned resources or report
133	  // metadata that later passes need.
134	  AddWorkspaceCallback add_workspace = nullptr;
135	  AllocMBarrierCallback alloc_mbarrier = nullptr;
136	  UpdateBarrierArriveCallback update_barrier_arrive = nullptr;
137	  // Optional callback to record a minimum shared-memory base alignment for a
138	  // buffer's data Var. Lowerings that bind a buffer to a swizzle-sensitive
139	  // instruction (TMA bulk copy, wgmma/tcgen05 descriptors) report the
140	  // alignment implied by the chosen swizzle mode here; LowerTileOp collects
141	  // the results into the kSmemAlignmentMap PrimFunc attribute.
142	  RequireSmemAlignmentCallback require_smem_alignment = nullptr;
143	};
144	
145	struct LayoutInferArgs {
146	  Target target;
147	  Range thread_bounds;
148	  LayoutMap layout_map;
149	  arith::Analyzer *analyzer;
150	  ffi::Map<tirx::Buffer, tirx::Buffer> buffer_remap;
151	  // Map from Bind variable to its bound expression, for resolving
152	  // fragment buffer accesses through Bind values
153	  ffi::Map<tirx::Var, PrimExpr> bind_var_to_expr;
154	  // Whether the current TileOp is nested inside a pipelined loop
155	  // (i.e. a surrounding loop annotated with num_stages > 0).
156	  bool in_pipeline = false;
157	};
158	
159	class TileOperator;
160	
161	class TileOperatorNode : public ffi::Object {
162	public:
163	  virtual tirx::Stmt Lower(const LowerArgs &lower_args,
164	                           arith::Analyzer *analyzer) const = 0;
165	
166	  virtual LayoutMap InferLayout(const LayoutInferArgs &layout_args,
167	                                InferLevel level) const = 0;
168	
169	  virtual TileOperator Clone() const = 0;
170	
171	  virtual AccessRegions GetAccessRegions() const {
172	    AccessRegions result;
173	    for (const auto &access : access_regions_) {
174	      AppendAccessRegionByMask(access, &result.reads, &result.writes);
175	    }
176	    return result;
177	  }
178	
179	  void SetAccessRegions(std::vector<AccessRegion> access_regions) {
180	    access_regions_ = std::move(access_regions);
181	  }
182	
183	  TVM_FFI_DECLARE_OBJECT_INFO("tl.TileOperator", TileOperatorNode, ffi::Object);
184	
185	protected:
186	  std::vector<AccessRegion> access_regions_;
187	};
188	
189	class TileOperator : public ffi::ObjectRef {
190	public:
191	  TVM_FFI_DEFINE_OBJECT_REF_METHODS_NULLABLE(TileOperator, ffi::ObjectRef,
192	                                             TileOperatorNode);
193	};
194	
195	tirx::Var GetVarFromAccessPtr(const PrimExpr &expr);
196	
