30	std::vector<GemmImpl> &GemmImplRegistry() {
31	  static std::vector<GemmImpl> registry;
32	  return registry;
33	}
34	
35	const GemmImpl &ResolveGemmImpl(Target target) {
36	  const auto &registry = GemmImplRegistry();
37	  const GemmImpl *matched_impl = nullptr;
38	  for (const GemmImpl &impl : registry) {
39	    if (impl.match_target(target)) {
40	      ICHECK(matched_impl == nullptr)
41	          << "tl.gemm found multiple target-specific implementations for "
42	          << target->str() << ": " << matched_impl->name << " and "
43	          << impl.name;
44	      matched_impl = &impl;
45	    }
46	  }
47	  ICHECK(matched_impl != nullptr)
48	      << "tl.gemm requires a target-specific implementation, but no gemm "
49	         "implementation is registered for "
50	      << target->str();
51	  return *matched_impl;
52	}
53	
54	} // namespace
55	
56	void RegisterGemmImpl(GemmImpl impl) {
57	  ICHECK(impl.name != nullptr);
58	  ICHECK(impl.match_target != nullptr);
59	  ICHECK(impl.select_inst != nullptr);
60	  ICHECK(impl.compute_warp_partition != nullptr);
61	  ICHECK(impl.reuse_existing_shared_layout != nullptr);
62	  GemmImplRegistry().push_back(impl);
63	}
64	
65	/**
66	 * @brief Construct a Gemm operator from serialized TL arguments.
67	 *
68	 * Deserializes operator parameters from `args` and resolves buffer references,
69	 * populating an internal GemmNode with buffers, transpose flags, M/N/K,
70	 * warp policy, clear_accum, strides, offsets, optional kPack/wg_wait, and
71	 * optional mbarrier.
72	 *
73	 * @param args Positional serialized arguments produced by the TL frontend:
74	 *   expected layout is:
75	 *     [Aptr, Bptr, Cptr, trans_A (Bool), trans_B (Bool),
76	 *      M (Int), N (Int), K (Int), policy (Int), clear_accum (Bool),
77	 *      stride_A (Int), stride_B (Int), offset_A (Int), offset_B (Int),
78	 *      (optional) kPack (Int), (optional) internal wg_wait (Int),
79	 *      (optional) mbar (BufferLoad), cCoord_y (PrimExpr), cCoord_x (PrimExpr)]
80	 */
81	Gemm::Gemm(Array<PrimExpr> args, Map<String, ObjectRef> annotations) {
82	  ObjectPtr<GemmNode> node = make_object<GemmNode>();
83	
84	  auto a_access = NormalizeToAccessRegion(args[0], kAccessRead);
85	  auto b_access = NormalizeToAccessRegion(args[1], kAccessRead);
86	  auto c_access = NormalizeToAccessRegion(args[2], kAccessReadWrite);
87	
88	  node->aRegion_ = a_access.region;
89	  node->bRegion_ = b_access.region;
90	  node->cRegion_ = c_access.region;
91	  node->SetAccessRegions({a_access, b_access, c_access});
92	
93	  node->a_ = node->aRegion_->buffer;
94	  node->b_ = node->bRegion_->buffer;
95	  node->c_ = node->cRegion_->buffer;
96	  node->transA_ = args[3].as<Bool>().value();
97	  node->transB_ = args[4].as<Bool>().value();
98	  node->m_ = args[5].as<IntImm>().value()->value;
99	  node->n_ = args[6].as<IntImm>().value()->value;
100	  node->k_ = args[7].as<IntImm>().value()->value;
101	  node->policy_ = GemmWarpPolicy(args[8].as<IntImm>().value()->value);
102	  node->clearAccum_ = args[9].as<PrimExpr>().value();
103	  node->strideA_ = args[10].as<IntImm>().value()->value;
104	  node->strideB_ = args[11].as<IntImm>().value()->value;
105	  node->offsetA_ = args[12].as<PrimExpr>().value();
106	  node->offsetB_ = args[13].as<PrimExpr>().value();
107	  if (args.size() > 14) {
108	    node->kPack_ = args[14].as<IntImm>().value()->value;
109	    if (node->kPack_ != 1 && node->kPack_ != 2) {
110	      ICHECK(false) << "kPack must be 1 or 2";
111	    }
112	  }
113	  if (args.size() > 15) {
114	    node->wgWait_ = args[15].as<IntImm>().value()->value;
115	  }
116	  if (auto val = annotations.Get("is_wgmma")) {
117	    const auto *int_val = val->as<IntImmNode>();
118	    ICHECK(int_val) << "is_wgmma annotation must be IntImmNode";
119	    node->isWgmma_ = int_val->value != 0;
120	  }
121	  if (auto val = annotations.Get("is_tcgen05")) {
122	    const auto *int_val = val->as<IntImmNode>();
123	    ICHECK(int_val) << "is_tcgen05 annotation must be IntImmNode";
124	    node->isTcgen05_ = int_val->value != 0;
125	  }
126	  if (args.size() > 16 && args[16]->IsInstance<BufferLoadNode>()) {
127	    node->mbar_ = Downcast<BufferLoad>(args[16]);
128	  }
129	  node->cCoords_ = Array<PrimExpr>(
130	      {args[17].as<PrimExpr>().value(), args[18].as<PrimExpr>().value()});
131	  if (args.size() > 19) {
132	    node->sfaRegion_ = NormalizeToBufferRegion(args[19]);
133	  }
134	  if (args.size() > 20) {
135	    node->sfbRegion_ = NormalizeToBufferRegion(args[20]);
136	  }
137	  if (args.size() > 21) {
138	    node->sfKStart_ = args[21].as<PrimExpr>().value();
139	  }
140	  node->annotations_ = annotations;
141	  data_ = std::move(node);
142	}
143	
144	AccessRegions GemmNode::GetAccessRegions() const {
145	  AccessRegions result;
146	  result.reads.push_back(aRegion_);
147	  result.reads.push_back(bRegion_);
148	  if (!is_one(clearAccum_)) {
149	    result.reads.push_back(cRegion_);
150	  }
151	  if (sfaRegion_.defined()) {
152	    result.reads.push_back(sfaRegion_);
153	  }
154	  if (sfbRegion_.defined()) {
155	    result.reads.push_back(sfbRegion_);
156	  }
157	  result.writes.push_back(cRegion_);
158	  return result;
159	}
160	
161	TileOperator GemmNode::Clone() const {
162	  auto op = make_object<GemmNode>(*this);
163	  return Gemm(op);
164	}
165	
166	String GemmNode::GetGemmInstructionKey(int block_size, Target target) const {
167	  return ResolveGemmImpl(target).select_inst(*this, block_size, target);
168	}
169	
170	std::pair<int, int> GemmWarpPolicyNode::ComputeWarpPartition(
171	    int M, int N, int block_size, Target target, String gemm_inst) const {
172	  return ResolveGemmImpl(target).compute_warp_partition(*this, M, N, block_size,
173	                                                        target, gemm_inst);
174	}
175	
176	Stmt GemmNode::Lower(const LowerArgs &lower_args,
177	                     arith::Analyzer *analyzer) const {
178	  if (const auto f = Function::GetGlobal("tl.gemm.lower")) {
179	    PrimExpr mbar_phase = lower_args.mbar_phase_expr;
180	    if (auto explicit_phase = GetAnnotatedMbarPhaseExpr(annotations_)) {
181	      mbar_phase = explicit_phase.value();
182	    }
183	    // NOTE(wt): Decide the instruction key and compute warp partition on Python
184	    // side.
185	    auto prim_func = Downcast<PrimFunc>(
186	        (*f)(GetRef<Gemm>(this), lower_args.layout_map, lower_args.target,
187	             lower_args.thread_bounds, lower_args.thread_index, mbar_phase));
188	    ICHECK(prim_func->attrs.defined());
189	    auto global_symbol = prim_func->attrs.GetAttr<String>("global_symbol");
190	    ICHECK(global_symbol.has_value());
191	    if (prim_func->body.as<SBlockRealizeNode>()) {
192	      SBlockRealize block_realize = Downcast<SBlockRealize>(prim_func->body);
193	      auto block = block_realize->block;
194	      {
195	        SBlockNode *n = block.CopyOnWrite();
196	        n->name_hint = global_symbol.value();
197	        n->annotations.Set(tl::attr::kLexicalAllocScope,
198	                           IntImm(DataType::Int(32), 1));
199	      }
200	      return SBlockRealize(block_realize->iter_values, block_realize->predicate,
201	                           block);
202	    }
203	    // wrap with block realize node
204	    Map<String, ObjectRef> block_annotations;
205	    block_annotations.Set(tl::attr::kLexicalAllocScope,
206	                          IntImm(DataType::Int(32), 1));
207	    return SBlockRealize(
208	        /*iter_values=*/Array<PrimExpr>(),
209	        /*predicate=*/const_true(),
210	        /*block=*/
211	        SBlock(/*iter_vars=*/{}, /*reads=*/{}, /*writes=*/{},
212	               /*name_hint=*/global_symbol.value(), prim_func->body,
213	               /*init=*/Optional<Stmt>(), /*alloc_buffers=*/{},
214	               /*match_buffers=*/{}, /*annotations=*/block_annotations));
215	  } else {
216	    LOG(FATAL) << "No lower function found for gemm";
217	    return Stmt();
218	  }
219	}
220	
221	LayoutMap GemmNode::InferLayout(const LayoutInferArgs &layout_args,
222	                                InferLevel level) const {
223	  if (completed_)
224	    return {};
225	  LayoutMap results;
226	  if (const auto f = Function::GetGlobal("tl.gemm.infer_layout")) {
227	    auto inferred_layouts = Downcast<LayoutMap>((*f)(
228	        GetRef<Gemm>(this), layout_args.target, layout_args.thread_bounds));
229	    // For MMA instructions, skip shared buffer layouts that are already
230	    // inferred by a prior operator to avoid layout conflicts when the same
231	    // shared buffer is consumed by multiple gemm ops with different transpose
232	    // semantics. WGMMA/TCGEN5MMA have strict shared memory layout requirements
233	    // and must always set their layouts.
234	    auto block_size = *as_const_int(layout_args.thread_bounds->extent);
235	    String gemm_inst = GetGemmInstructionKey(block_size, layout_args.target);
236	    bool reuse_existing_shared_layout =
237	        ResolveGemmImpl(layout_args.target)
238	            .reuse_existing_shared_layout(gemm_inst);
239	    for (auto kv : inferred_layouts) {
240	      const Buffer &buf = kv.first;
241	      const Layout &layout = kv.second;
242	      if (reuse_existing_shared_layout && IsSharedBuffer(buf) &&
243	          layout_args.layout_map.count(buf)) {
244	        continue;
245	      }
246	      if (auto frag = layout.as<Fragment>()) {
247	        results.Set(buf,
248	                    frag.value()->BindThreadRange(layout_args.thread_bounds));
249	      } else {
250	        results.Set(buf, layout);
251	      }
252	    }
253	  } else {
254	    LOG(FATAL) << "No infer layout function found for gemm";
255	  }
256	
257	  completed_ = true;
258	  return results;
259	}
260	
261	TIR_REGISTER_TL_TILE_OP(Gemm, gemm)
262	    .set_num_inputs(-1)
263	    .set_attr<TCallEffectKind>("TCallEffectKind",
264	                               Integer(CallEffectKind::kOpaque));
265	
266	TVM_REGISTER_OP("tl.tileop.wgmma_gemm")
267	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "wgmma_gemm")
268	    .set_attr<OpBuilderFunc>("TLOpBuilder",
269	                             [](Array<PrimExpr> args,
270	                                Map<String, ObjectRef> annotations) {
271	                               Map<String, ObjectRef> ann = annotations;
272	                               ann.Set("is_wgmma",
273	                                       IntImm(DataType::Int(32), 1));
274	                               return Gemm(args, ann);
275	                             })
276	    .set_num_inputs(-1)
277	    .set_attr<TCallEffectKind>("TCallEffectKind",
278	                               Integer(CallEffectKind::kOpaque));
279	
280	TVM_REGISTER_OP("tl.tileop.tcgen05_gemm")
281	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "tcgen05_gemm")
282	    .set_attr<OpBuilderFunc>("TLOpBuilder",
283	                             [](Array<PrimExpr> args,
284	                                Map<String, ObjectRef> annotations) {
285	                               Map<String, ObjectRef> ann = annotations;
286	                               ann.Set("is_tcgen05",
287	                                       IntImm(DataType::Int(32), 1));
288	                               return Gemm(args, ann);
289	                             })
290	    .set_num_inputs(-1)
291	    .set_attr<TCallEffectKind>("TCallEffectKind",
292	                               Integer(CallEffectKind::kOpaque));
293	
294	TVM_REGISTER_OP("tl.GemmWarpPolicy")
295	    .set_attr<TScriptPrinterName>("TScriptPrinterName", "GemmWarpPolicy");
296	
297	TVM_FFI_STATIC_INIT_BLOCK() {
298	  GemmNode::RegisterReflection();
299	  GemmWarpPolicyNode::RegisterReflection();
300	  namespace refl = reflection;
301	  refl::GlobalDef().def("tl.GemmWarpPolicyComputeWarpPartition",
302	                        [](GemmWarpPolicy policy, int M, int N, int block_size,
303	                           Target target, String gemm_inst) {
304	                          policy->ComputeWarpPartition(M, N, block_size, target,
305	                                                       gemm_inst);
306	                        });
307	  refl::GlobalDef().def("tl.GemmGetGemmInstructionKey",
308	                        [](Gemm gemm, int block_size, Target target) {
309	                          return gemm->GetGemmInstructionKey(block_size,
310	                                                             target);
311	                        });
312	}
313	
314	} // namespace tl
315	} // namespace tvm
