from __future__ import annotations

from dataclasses import dataclass
from tilelang import tvm as tvm
from tvm.target import Target
from tvm.ir import Range
from tvm import tirx
from tilelang import language as T
from tilelang.utils.language import is_shared, is_fragment, is_tensor_memory
from tilelang.tileop.base import GemmWarpPolicy
from tilelang.language.dtypes import validate_gemm_ab_dtypes
from tvm.ir.base import Node
from tvm.ir import PrimExpr


@dataclass
class GemmBase:
    """Base class for GEMM tile operators.

    Classifies the GEMM variant by the memory scopes of operands A and B
    (SS, SR, RS, TS, RR) and provides common property accessors for the
    underlying ``gemm_node`` IR node.
    """

    gemm_node: Node

    def __post_init__(self) -> None:
        validate_gemm_ab_dtypes(
            self.A.dtype,
            self.B.dtype,
            a_in_tmem=is_tensor_memory(self.A),
            allow_f8f6f4_mixed=self.allow_f8f6f4_mixed_dtypes,
        )

    @property
    def allow_f8f6f4_mixed_dtypes(self) -> bool:
        # TODO(wt): Consider enabling mixed f8f6f4 operands for MMA paths too.
        return False

    def infer_layout(self, target: Target, thread_nums: int):
        raise NotImplementedError("infer_layout is not implemented")

    def lower(
        self,
        layout_map: dict,
        target: Target,
        thread_bounds: Range,
        thread_index: tirx.PrimExpr,
        mbar_phase_expr: tirx.PrimExpr | None = None,
    ):
        raise NotImplementedError("lower is not implemented")

    def is_gemm_ss(self) -> bool:
        """Return True if both A and B are in shared memory (SS variant)."""
        return is_shared(self.A) and is_shared(self.B)

    def is_gemm_sr(self) -> bool:
        """Return True if A is in shared memory and B is in registers (SR variant)."""
        return is_shared(self.A) and is_fragment(self.B)

    def is_gemm_rs(self) -> bool:
        """Return True if A is in registers and B is in shared memory (RS variant)."""
        return is_fragment(self.A) and is_shared(self.B)

    def is_gemm_ts(self) -> bool:
        """Return True if A is in tensor memory and B is in shared memory (TS variant)."""
        return is_tensor_memory(self.A) and is_shared(self.B)

    def is_gemm_rr(self) -> bool:
        """Return True if both A and B are in registers (RR variant)."""
        return is_fragment(self.A) and is_fragment(self.B)

    @property
    def M(self) -> int:
        return getattr(self.gemm_node, "m", None)

    @property
    def N(self) -> int:
        return getattr(self.gemm_node, "n", None)

    @property
    def K(self) -> int:
        return getattr(self.gemm_node, "k", None)

    @property
    def trans_A(self) -> bool:
        return getattr(self.gemm_node, "transA", None)

    @property
    def trans_B(self) -> bool:
        return getattr(self.gemm_node, "transB", None)

    @property
    def a_dtype(self):
        """A operand dtype."""
        return self.A.dtype

    @property
    def b_dtype(self):
        """B operand dtype."""
        return self.B.dtype

    @property
    def accum_dtype(self) -> str:
        return self.C.dtype

    @property
    def chunk(self) -> int:
        return self.K

    @property
    def A(self) -> tirx.Buffer:
        return getattr(self.gemm_node, "a", None)

    @property
    def B(self) -> tirx.Buffer:
        return getattr(self.gemm_node, "b", None)

    @property
    def C(self) -> tirx.Buffer:
        return getattr(self.gemm_node, "c", None)

    @property
    def ARegion(self):
        return getattr(self.gemm_node, "aRegion", None)

    @property
    def BRegion(self):
        return getattr(self.gemm_node, "bRegion", None)

    @property
    def CRegion(self):
        return getattr(self.gemm_node, "cRegion", None)

    @property
    def stride_A(self) -> int:
        return getattr(self.gemm_node, "strideA", None)

    @property
    def stride_B(self) -> int:
        return getattr(self.gemm_node, "strideB", None)

    @property
    def offset_A(self) -> int:
        return getattr(self.gemm_node, "offsetA", None)

    @property
    def offset_B(self) -> int:
        return getattr(self.gemm_node, "offsetB", None)

    @property
    def clear_accum(self) -> PrimExpr:
        return getattr(self.gemm_node, "clearAccum", None)

    @property
    def k_pack(self) -> int:
        return getattr(self.gemm_node, "kPack", None)

    @property
    def wg_wait(self) -> int:
        return getattr(self.gemm_node, "wgWait", 0)

    @property
    def is_tcgen05(self) -> bool:
        return getattr(self.gemm_node, "isTcgen05", False)

    @property
    def policy(self) -> GemmWarpPolicy:
        return getattr(self.gemm_node, "policy", None)

    @property
    def mbarptr(self) -> PrimExpr:
        return getattr(self.gemm_node, "mbarPtr", tvm.tirx.const(0, T.uint32))

    @property
    def mbar(self) -> tirx.BufferLoad | None:
        return getattr(self.gemm_node, "mbar", None)

    @property
    def C_coords(self):
        coords = getattr(self.gemm_node, "cCoords", None)
        if coords is None or len(coords) == 0:
            zero = tvm.tirx.const(0, T.int32)
            return [zero, zero]
        return [coords[i] for i in range(len(coords))]

    @property
    def SFARegion(self):
        return getattr(self.gemm_node, "sfaRegion", None)

    @property
    def SFBRegion(self):
        return getattr(self.gemm_node, "sfbRegion", None)

    @property
    def sf_k_start(self) -> PrimExpr:
        return getattr(self.gemm_node, "sfKStart", tvm.tirx.const(0, T.int32))

    @property
    def is_blockscaled(self) -> bool:
        return self.SFARegion is not None and self.SFBRegion is not None

    def get_region_base_offsets(self, region):
        """
        Get the base offset (start index) for each dimension from a BufferRegion.

        For example, if region is A_shared[ko % 2, 0:128, 0:64],
        this returns [ko % 2, 0, 0]

        Args:
            region: BufferRegion object

        Returns:
            List of PrimExpr representing the base offset for each dimension
        """
        if region is None:
            return []
        return [r.min for r in region.region]

    @property
    def A_base_offsets(self):
        """Get base offsets for each dimension of A region"""
        return self.get_region_base_offsets(self.ARegion)

    @property
    def B_base_offsets(self):
        """Get base offsets for each dimension of B region"""
        return self.get_region_base_offsets(self.BRegion)

    @property
    def C_base_offsets(self):
        """Get base offsets for each dimension of C region"""
        return self.get_region_base_offsets(self.CRegion)

"""Device codegen registry shared by backend packages."""

from __future__ import annotations

from collections.abc import Callable
from dataclasses import dataclass
from importlib import import_module

from tvm import IRModule
from tvm.target import Target

from tilelang import tvm

DeviceCodegenFunc = Callable[[IRModule, Target], IRModule]
TargetPredicate = Callable[[Target], bool]


def global_func_device_codegen(global_func_name: str) -> DeviceCodegenFunc:
    """Create a device codegen callback backed by a TVM global function."""

    def build(mod: IRModule, target: Target) -> IRModule:
        return tvm.ffi.get_global_func(global_func_name)(mod, target)

    return build


@dataclass(frozen=True, slots=True)
class DeviceCodegen:
    """Device codegen entry points for one backend target variant."""

    name: str
    build: DeviceCodegenFunc | None = None
    build_without_compile: DeviceCodegenFunc | None = None
    supports_target: TargetPredicate | None = None

    def matches(self, target: Target) -> bool:
        return True if self.supports_target is None else self.supports_target(target)

    def lower(self, mod: IRModule, target: Target, *, compile_device: bool) -> IRModule:
        build_func = self.build if compile_device else self.build_without_compile
        if build_func is None:
            mode = "with compilation" if compile_device else "without compilation"
            raise ValueError(f"Device codegen '{self.name}' for target '{target.kind.name}' does not support lowering {mode}")
        return build_func(mod, target)


_DEVICE_CODEGENS: dict[str, list[DeviceCodegen]] = {}
_LAZY_DEVICE_CODEGENS: dict[str, str] = {}
_LOADED_DEVICE_CODEGENS: set[str] = set()


def register_device_codegen(
    target_kind: str,
    codegen: DeviceCodegen,
    *,
    override: bool = False,
) -> DeviceCodegen:
    """Register a device codegen entry for a target kind."""

    codegens = _DEVICE_CODEGENS.setdefault(target_kind, [])
    if override:
        codegens[:] = [item for item in codegens if item.name != codegen.name]
    elif any(item.name == codegen.name for item in codegens):
        raise ValueError(f"Device codegen {codegen.name!r} is already registered for target kind {target_kind!r}")
    codegens.append(codegen)
    return codegen


def register_lazy_device_codegen(target_kind: str, import_path: str) -> None:
    """Register a backend module to import when its target kind is first used."""

    _LAZY_DEVICE_CODEGENS[target_kind] = import_path
    _LOADED_DEVICE_CODEGENS.discard(target_kind)


def _ensure_device_codegens_loaded(target_kind: str) -> None:
    if target_kind in _LOADED_DEVICE_CODEGENS:
        return
    import_path = _LAZY_DEVICE_CODEGENS.get(target_kind)
    if import_path is not None:
        import_module(import_path)
    _LOADED_DEVICE_CODEGENS.add(target_kind)


def _matching_device_codegens(target: Target) -> list[DeviceCodegen]:
    target_kind = target.kind.name
    _ensure_device_codegens_loaded(target_kind)
    return [codegen for codegen in _DEVICE_CODEGENS.get(target_kind, ()) if codegen.matches(target)]


def allowed_device_codegens_for_target(target: Target) -> list[str]:
    """Return matching device codegen names for a target."""

    return [codegen.name for codegen in _matching_device_codegens(target)]


def _format_codegen_names(codegens: list[DeviceCodegen]) -> str:
    names = [codegen.name for codegen in codegens]
    return ", ".join(names) if names else "<none>"


def resolve_device_codegen(target: Target) -> DeviceCodegen:
    """Resolve a device codegen entry from a TVM target."""

    matches = _matching_device_codegens(target)
    if not matches:
        target_kind = target.kind.name
        options = _format_codegen_names(_DEVICE_CODEGENS.get(target_kind, []))
        raise ValueError(f"No device codegen registered for target '{target_kind}'. Available: {options}.")
    return matches[0]

